using System.Collections;
using UnityEngine;
using UnityEngine.AddressableAssets;
using UnityEngine.ResourceManagement.AsyncOperations;
using UnityEngine.ResourceManagement.ResourceProviders;

namespace Astrea;

public class TransitionCanvas : MonoBehaviour
{
	[SerializeField]
	private FadeCanvasGroup fadeCanvasGroup;

	[SerializeField]
	private float delayToFadeOut = 0.6f;

	[SerializeField]
	private Transform transitionBackground;

	private WaitForSeconds waitToFadeOut;

	private Coroutine coroutineLoadScene;

	public static TransitionCanvas Instance;

	public Coroutine CoroutineLoadScene => coroutineLoadScene;

	private void Awake()
	{
		if (!Instance)
		{
			Instance = this;
			Object.DontDestroyOnLoad(base.gameObject);
		}
		else
		{
			Object.Destroy(base.gameObject);
		}
		waitToFadeOut = new WaitForSeconds(delayToFadeOut);
	}

	private IEnumerator Start()
	{
		yield return null;
		UpdateSafeFrameSize();
	}

	public void FadeTransitionLoadSceneAsync(int sceneIndex)
	{
		if (coroutineLoadScene != null)
		{
			StopCoroutine(coroutineLoadScene);
		}
		fadeCanvasGroup.Fade(toggle: true, delegate
		{
			coroutineLoadScene = StartCoroutine(StartLoadSceneRoutine(sceneIndex));
		});
	}

	private IEnumerator StartLoadSceneRoutine(int sceneIndex)
	{
		UpdateSafeFrameSize();
		AsyncOperationHandle<SceneInstance> asyncLoad = Addressables.LoadSceneAsync(GameScenesUtils.GetSceneNameFromSceneIndex(sceneIndex));
		while (!asyncLoad.IsDone)
		{
			yield return null;
		}
		Time.timeScale = 1f;
		yield return waitToFadeOut;
		fadeCanvasGroup.Fade(toggle: false, delegate
		{
			if ((bool)ReferenceSingleton<GameStateManager>.Instance)
			{
				ReferenceSingleton<GameStateManager>.Instance.SetLoading(value: false);
			}
		});
		coroutineLoadScene = null;
	}

	public void UpdateSafeFrameSize()
	{
	}
}
